@@ -42,16 +42,13 @@
-    public Registration addRegistrationAndAssignToSkierAndCourse(Registration registration, Long numSkier, Long numCourse) {
-        Skier skier = skierRepository.findById(numSkier).get();
-        Course course = courseRepository.findById(numCourse).get();
-
-        if (course.getTypeCourse().equals(TypeCourse.COLLECTIVE_CHILD) || course.getTypeCourse().equals(TypeCourse.COLLECTIVE_ADULT)) {
-            if (registrationRepository.countByCourseAndDate(course, registration.getDate()) < 6) {
-                registration.setSkier(skier);
-                registration.setCourse(course);
-                return registrationRepository.save(registration);
-            } else {
-                return null;
-            }
-        }
-        registration.setSkier(skier);
-        registration.setCourse(course);
-        return registrationRepository.save(registration);
+    public Registration addRegistrationAndAssignToSkierAndCourse(Registration registration, Long numSkier, Long numCourse) {
+        Skier skier = skierRepository.findById(numSkier).orElse(null);
+        Course course = courseRepository.findById(numCourse).orElse(null);
+        if (skier == null || course == null || isCourseFull(course, registration)) {
+            return null;
+        }
+        registration.setSkier(skier);
+        registration.setCourse(course);
+        return registrationRepository.save(registration);
+    }
+
+    private boolean isCourseFull(Course course, Registration registration) {
+        boolean isCollective = course.getTypeCourse().name().contains("COLLECTIVE");
+        return isCollective && registrationRepository.countByCourseAndDate(course, registration.getDate()) >= 6;
+    }

